import React from 'react';

export default function StudentDashboard({ userName, userId, handleLogout }) {
  
  return (
    <div style={{ flex: 1, backgroundColor: '#f4f7f5', padding: '30px', fontFamily: 'sans-serif' }}>
      
      {/* Welcome Banner */}
      <div style={{ backgroundColor: '#fff', padding: '24px', borderRadius: '16px', boxShadow: '0 4px 20px rgba(0,0,0,0.02)', borderLeft: '6px solid #388e3c', marginBottom: '25px' }}>
        <h2 style={{ margin: 0, color: '#1e293b', fontSize: '24px', fontWeight: '700' }}>👋 Welcome, HNCOE/PE/2026/03</h2>
        <p style={{ margin: '5px 0 0 0', color: '#64748b', fontSize: '14px' }}>Access your courses, quizzes, learning materials, and academic activities.</p>
      </div>

      {/* 4 Analytics Cards (යාළුවාගේ 10 වැනි පින්තූරේ තිබ්බ ටික) */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginBottom: '30px' }}>
        {[
          { title: 'Enrolled Courses', count: '1', color: '#e0f2fe', textColor: '#0369a1' },
          { title: 'Total Subjects', count: '1', color: '#dcfce7', textColor: '#15803d' },
          { title: 'Learning Materials', count: '1', color: '#fef9c3', textColor: '#ca8a04' },
          { title: 'Total Quizzes', count: '2', color: '#f3e8ff', textColor: '#6b21a8' }
        ].map((card, i) => (
          <div key={i} style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 10px rgba(0,0,0,0.01)', border: '1px solid #e2e8f0' }}>
            <p style={{ margin: '0 0 10px 0', color: '#64748b', fontSize: '13px', fontWeight: '600' }}>🔹 {card.title}</p>
            <h2 style={{ margin: 0, color: card.textColor, fontSize: '28px', fontWeight: '700' }}>{card.count}</h2>
          </div>
        ))}
      </div>

      {/* Academic Courses Display Section */}
      <div style={{ backgroundColor: '#fff', padding: '24px', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.02)' }}>
        <h3 style={{ margin: '0 0 20px 0', color: '#1e293b', fontSize: '18px', fontWeight: '600' }}>📘 My Academic Courses</h3>
        
        <div style={{ padding: '15px', border: '1px solid #e2e8f0', borderRadius: '8px', maxWidth: '300px', backgroundColor: '#fafafa' }}>
          <h4 style={{ margin: '0 0 5px 0', color: '#388e3c' }}>Primary Education</h4>
          <span style={{ fontSize: '12px', backgroundColor: '#f1f5f9', padding: '2px 6px', borderRadius: '4px', color: '#475569', fontWeight: '600' }}>PE</span>
          <p style={{ margin: '15px 0 10px 0', fontSize: '14px', color: '#334155' }}>✓ Religion</p>
          <button style={{ width: '100%', backgroundColor: '#e8f5e9', color: '#388e3c', border: 'none', padding: '8px', borderRadius: '6px', fontSize: '13px', fontWeight: '600', cursor: 'pointer' }}>
            📖 View Materials
          </button>
        </div>
      </div>

      {/* Logout Button */}
      <button onClick={handleLogout} style={{ marginTop: '20px', backgroundColor: '#dc2626', color: '#fff', border: 'none', padding: '10px 20px', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
        Logout
      </button>

    </div>
  );
}
